@pytest.mark.tc('TC_SETT_010')
def test_tc_sett_010_cancel_or_close_delete_confirmation_reta(app):
    """TC_SETT_010: Cancel or close delete confirmation retains account

    Scenario: SC_SETT_003
    Expected: Navigating away cancels the deletion flow; the account remains intact and the Settings page returns to its normal state.
    Note: Precondition: delete confirmation UI is visible. The script navigates away by clicking the  Settings  radio in the sidebar (which is the current view) and verifies the confirmation UI disappears and the  Delete my account  button reappears.
    """
    with app.step('Open the page under test', action='goto', element=''):
        app.goto('/~/+/')
    with app.step("Click the 'Settings' radio button in the sidebar to navigate away (cancels the deletion flow).", action='click', element='settings.settings_radio'):
        app.pages.settings.settings_radio.click()
    with app.step('Verify the deletion warning text is no longer visible.', action='expect_hidden', element='settings.deleting_your_account_permanently_remove_div'):
        app.pages.settings.deleting_your_account_permanently_remove_div.expect_hidden()
    with app.step('Verify the understanding checkbox is no longer visible.', action='expect_hidden', element='settings.i_understand_this_permanently_deletes_my_checkbox'):
        app.pages.settings.i_understand_this_permanently_deletes_my_checkbox.expect_hidden()
    with app.step('Verify the email confirmation textbox is no longer visible.', action='expect_hidden', element='settings.type_your_email_address_to_confirm_delet_textbox'):
        app.pages.settings.type_your_email_address_to_confirm_delet_textbox.expect_hidden()
    with app.step("Verify the 'Delete my account' button is visible again.", action='expect_visible', element='settings.delete_my_account_button'):
        app.pages.settings.delete_my_account_button.expect_visible()

